import{_ as t,o as r,c as a,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"External Rook Ceph Cluster - Parth Arora & Subham Rai, IBM","description":"","frontmatter":{"title":"External Rook Ceph Cluster - Parth Arora & Subham Rai, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Kubernetes","Rook Operator","Distributed Storage","Storage Orchestration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/External_Rook_Ceph_Cluster_-_Parth_Arora_Subham_Rai_IBM.md","filePath":"posts/2023/External_Rook_Ceph_Cluster_-_Parth_Arora_Subham_Rai_IBM.md","lastUpdated":1780459816000}'),o={name:"posts/2023/External_Rook_Ceph_Cluster_-_Parth_Arora_Subham_Rai_IBM.md"};function i(s,e,n,h,u,_){return r(),a("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议参与者" tabindex="-1">会议参与者 <a class="header-anchor" href="#会议参与者" aria-label="Permalink to &quot;会议参与者&quot;">​</a></h4><ul><li><strong>Parth</strong> 和 <strong>Shubham</strong>，IBM 存储部门的研发人员，主要负责 Rook operator 的开发。</li></ul><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><ul><li>讨论外部 Ceph 集群的需求、使用场景、实现方式以及未来的工作计划。</li></ul><h4 id="主要讨论内容" tabindex="-1">主要讨论内容 <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容&quot;">​</a></h4><ol><li><p><strong>外部 Ceph 集群的需求和使用场景</strong></p><ul><li><strong>需求背景</strong>：在 Kubernetes 集群中运行存储服务，但可能存在已经运行的外部 Ceph 集群，需要将其集成到 Kubernetes 环境中。</li><li><strong>使用场景</strong>： <ul><li>大型组织可能需要多个 Kubernetes 集群，通过单一的外部 Ceph 集群来管理这些集群的存储需求。</li><li>已经拥有 Ceph 集群，希望将其集成到 Kubernetes 环境中以实现自动化管理。</li><li>需要实现存储的完全隔离。</li></ul></li></ul></li><li><p><strong>外部 Ceph 集群的实现方式</strong></p><ul><li><strong>架构描述</strong>：通过 Rook operator 在外部模式下运行，并结合 CSI 层，从外部 Ceph 集群获取信息并提供给 Kubernetes 集群。</li><li><strong>安装和配置</strong>： <ul><li>使用 Python 脚本从外部 Ceph 集群获取详细信息。</li><li>通过导入 JSON 输出，创建 Kubernetes 资源如 Secrets、ConfigMaps 和 StorageClasses。</li><li>部署 Rook operator 并配置外部 Ceph 集群的连接。</li></ul></li></ul></li><li><p><strong>验证和监控</strong></p><ul><li><strong>验证连接</strong>：通过检查集群的健康状态和连接状态来验证配置是否成功。</li><li><strong>监控</strong>：通过不同的 OpenShift 集群（OCP）的仪表盘来监控不同外部 Ceph 集群的使用情况。</li></ul></li><li><p><strong>未来工作计划</strong></p><ul><li><strong>功能增强</strong>：支持 RADOS 命名空间、卷组和 IPv6 端点。</li><li><strong>文档改进</strong>：提供更清晰的文档，以便用户更容易连接和使用外部 Ceph 集群。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了外部 Ceph 集群的实现方式和使用场景。</li><li>确定了未来工作的重点，包括功能增强和文档改进。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续开发和测试外部 Ceph 集群的功能。</li><li>更新和改进相关文档，确保用户能够顺利使用外部 Ceph 集群。</li><li>监控和收集用户反馈，以便进一步优化和扩展功能。</li></ul>',11)])])}const g=t(o,[["render",i]]);export{d as __pageData,g as default};
